css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader::before { content: ''; position: absolute; top: 4%; left: 50%; width: 2px; height: 40%; margin-left: -1px; background: color-mix(in srgb, #000 25%, var(--accent)); transform-origin: top center; animation: string calc(var(--loader-speed) * 1.4) ease-in-out infinite; }
.loader span { position: absolute; top: 36%; left: 50%; width: calc(var(--loader-size) * .34); height: calc(var(--loader-size) * .34); margin-left: calc(var(--loader-size) * -.17); border-radius: 50%; background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 30%, var(--accent)), var(--accent) 60%, var(--accent-2)); animation: yoyo calc(var(--loader-speed) * 1.4) ease-in-out infinite, yospin calc(var(--loader-speed) * .35) linear infinite; }
.loader span::after { content: ''; position: absolute; inset: 40%; border-radius: 50%; background: color-mix(in srgb, #000 25%, var(--accent-2)); }
@keyframes yoyo { 0%, 100% { translate: 0 0; } 50% { translate: 0 48%; } }
@keyframes yospin { to { rotate: 360deg; } }
@keyframes string { 0%, 100% { transform: scaleY(1); } 50% { transform: scaleY(2.15); } }
